"""Sortie ZF2, batch 3: unit lifting from Dirichlet's theorem (coprmlift),
injectivity of changeLevel (dchrindinj), vanishing off units (dchrzrh0),
the CRT value of a product of induced characters (dchrindmulval)."""
import sys, os; sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..')); from tm import *
from zf2lib import *
only = sys.argv[1:]
def run(w):
    if only and w.label not in only: return True
    return w.run()

def dchr_hyps(w, n):
    return (w.s([], 'eqid', '( DChr ` %s ) = ( DChr ` %s )' % (n, n)),
            w.s([], 'eqid', '( Z/nZ ` %s ) = ( Z/nZ ` %s )' % (n, n)),
            w.s([], 'eqid', '%s = %s' % (DB(n), DB(n))),
            w.s([], 'eqid', '%s = %s' % (LZ(n), LZ(n))))

# ---- coprmliftlem: an infinite set of positive integers exceeds any bound
HL = '( S C_ NN /\\ -. S e. Fin /\\ M e. NN )'
w = W('coprmliftlem', 'Lemma for coprmlift: an infinite set of positive integers has an element above any given bound.')
s = w.s([], 'simp1', '( %s -> S C_ NN )' % HL); nf = w.s([], 'simp2', '( %s -> -. S e. Fin )' % HL); m = w.s([], 'simp3', '( %s -> M e. NN )' % HL)
A2 = '( %s /\\ A. p e. S -. M < p )' % HL; A3 = '( %s /\\ q e. S )' % A2
ps = w.s([], 'simpr', '( %s -> q e. S )' % A3)
pn = w.s([w.s([s], 'ad2antrr', '( %s -> S C_ NN )' % A3), ps], 'sseldd', '( %s -> q e. NN )' % A3)
m3 = w.s([m], 'ad2antrr', '( %s -> M e. NN )' % A3)
sb = w.s([w.s([], 'breq2', '( p = q -> ( M < p <-> M < q ) )')], 'notbid', '( p = q -> ( -. M < p <-> -. M < q ) )')
nl = w.s([w.s([], 'simplr', '( %s -> A. p e. S -. M < p )' % A3), ps, w.s([sb], 'rspccva', '( ( A. p e. S -. M < p /\\ q e. S ) -> -. M < q )')], 'syl2anc', '( %s -> -. M < q )' % A3)
le = w.s([w.s([pn], 'nnred', '( %s -> q e. RR )' % A3), w.s([m3], 'nnred', '( %s -> M e. RR )' % A3), w.inst('lenlt')], 'syl2anc', '( %s -> ( q <_ M <-> -. M < q ) )' % A3)
le2 = w.s([nl, le], 'mpbird', '( %s -> q <_ M )' % A3)
fz = w.s([w.s([pn, m3, le2], '3jca', '( %s -> ( q e. NN /\\ M e. NN /\\ q <_ M ) )' % A3), w.inst('elfz1b')], 'sylibr', '( %s -> q e. ( 1 ... M ) )' % A3)
fz2 = w.s([fz], 'ex', '( %s -> ( q e. S -> q e. ( 1 ... M ) ) )' % A2)
ss = w.s([fz2], 'ssrdv', '( %s -> S C_ ( 1 ... M ) )' % A2)
fi = w.s([w.s([w.s([], 'fzfi', '( 1 ... M ) e. Fin')], 'a1i', '( %s -> ( 1 ... M ) e. Fin )' % A2), ss, w.inst('ssfi')], 'syl2anc', '( %s -> S e. Fin )' % A2)
fi2 = w.s([fi], 'ex', '( %s -> ( A. p e. S -. M < p -> S e. Fin ) )' % HL)
nr = w.s([nf, fi2], 'mtod', '( %s -> -. A. p e. S -. M < p )' % HL)
w.qed([nr, w.s([], 'dfrex2', '( E. p e. S M < p <-> -. A. p e. S -. M < p )')], 'sylibr', '( %s -> E. p e. S M < p )' % HL); run(w)

# ---- coprmlift: a class coprime to N contains an integer coprime to M (Dirichlet)
HC = '( ( N e. NN /\\ M e. NN ) /\\ A e. ZZ /\\ ( A gcd N ) = 1 )'
SP = '{ q e. Prime | N || ( q - A ) }'
w = W('coprmlift', 'Unit lifting (Mathlib ZMod.unitsMap_surjective): every integer A coprime to N is congruent mod N to an integer coprime to M. Proved from Dirichlet\'s theorem dirith: the primes congruent to A mod N are infinite, so one of them exceeds M and is therefore coprime to M.')
n = w.s([], 'simp1l', '( %s -> N e. NN )' % HC); m = w.s([], 'simp1r', '( %s -> M e. NN )' % HC); a = w.s([], 'simp2', '( %s -> A e. ZZ )' % HC); c = w.s([], 'simp3', '( %s -> ( A gcd N ) = 1 )' % HC)
SP0 = SP.replace('q e. Prime | N || ( q - A )', 'p e. Prime | N || ( p - A )')
di0 = w.s([n, a, c, w.inst('dirith')], 'syl3anc', '( %s -> %s ~~ NN )' % (HC, SP0))
cbv = w.s([w.s([w.s([], 'oveq1', '( p = q -> ( p - A ) = ( q - A ) )')], 'breq2d', '( p = q -> ( N || ( p - A ) <-> N || ( q - A ) ) )')], 'cbvrabv', '%s = %s' % (SP0, SP))
di = w.s([cbv, di0], 'eqbrtrrid', '( %s -> %s ~~ NN )' % (HC, SP))
en = w.s([di, w.inst('enfi')], 'syl', '( %s -> ( %s e. Fin <-> NN e. Fin ) )' % (HC, SP))
nf = w.s([w.s([w.s([], 'nnnfi', '-. NN e. Fin')], 'a1i', '( %s -> -. NN e. Fin )' % HC), en], 'mtbird', '( %s -> -. %s e. Fin )' % (HC, SP))
ss = w.s([w.s([w.s([], 'ssrab2', '%s C_ Prime' % SP), w.s([], 'prmssnn', 'Prime C_ NN')], 'sstri', '%s C_ NN' % SP)], 'a1i', '( %s -> %s C_ NN )' % (HC, SP))
ex = w.s([ss, nf, m, w.inst('coprmliftlem')], 'syl3anc', '( %s -> E. p e. %s M < p )' % (HC, SP))
A2 = '( %s /\\ ( p e. %s /\\ M < p ) )' % (HC, SP)
pm = w.s([], 'simprl', '( %s -> p e. %s )' % (A2, SP)); lt = w.s([], 'simprr', '( %s -> M < p )' % A2)
el = w.s([w.s([w.s([], 'oveq1', '( q = p -> ( q - A ) = ( p - A ) )')], 'breq2d', '( q = p -> ( N || ( q - A ) <-> N || ( p - A ) ) )')], 'elrab', '( p e. %s <-> ( p e. Prime /\\ N || ( p - A ) ) )' % SP)
pr = w.s([pm, el], 'sylib', '( %s -> ( p e. Prime /\\ N || ( p - A ) ) )' % A2)
pp = w.s([pr], 'simpld', '( %s -> p e. Prime )' % A2); dv = w.s([pr], 'simprd', '( %s -> N || ( p - A ) )' % A2)
pz = w.s([pp], 'prmzd' if False else 'syl', '( %s -> p e. ZZ )' % A2)
w.lines.pop()
pz = w.s([pp, w.s([], 'prmz', '( p e. Prime -> p e. ZZ )')], 'syl', '( %s -> p e. ZZ )' % A2)
m2 = w.s([m], 'adantr', '( %s -> M e. NN )' % A2)
dl = w.s([pz, m2, w.inst('dvdsle')], 'syl2anc', '( %s -> ( p || M -> p <_ M ) )' % A2)
nle = w.s([w.s([m2], 'nnred', '( %s -> M e. RR )' % A2), w.s([w.s([pp, w.s([], 'prmnn', '( p e. Prime -> p e. NN )')], 'syl', '( %s -> p e. NN )' % A2)], 'nnred', '( %s -> p e. RR )' % A2), w.inst('ltnle')], 'syl2anc', '( %s -> ( M < p <-> -. p <_ M ) )' % A2)
nle2 = w.s([lt, nle], 'mpbid', '( %s -> -. p <_ M )' % A2)
nd = w.s([nle2, dl], 'mtod', '( %s -> -. p || M )' % A2)
cp = w.s([w.s([pp, w.s([m2], 'nnzd', '( %s -> M e. ZZ )' % A2), w.inst('coprm')], 'syl2anc', '( %s -> ( -. p || M <-> ( p gcd M ) = 1 ) )' % A2), nd], 'mpbid' if False else 'mpbid', '( %s -> ( p gcd M ) = 1 )' % A2)
w.lines.pop(); w.lines.pop()
cpb = w.s([pp, w.s([m2], 'nnzd', '( %s -> M e. ZZ )' % A2), w.inst('coprm')], 'syl2anc', '( %s -> ( -. p || M <-> ( p gcd M ) = 1 ) )' % A2)
cp = w.s([nd, cpb], 'mpbid', '( %s -> ( p gcd M ) = 1 )' % A2)
bo = w.s([dv, cp], 'jca', '( %s -> ( N || ( p - A ) /\\ ( p gcd M ) = 1 ) )' % A2)
s1 = w.s([], 'oveq1', '( b = p -> ( b - A ) = ( p - A ) )'); s2 = w.s([s1], 'breq2d', '( b = p -> ( N || ( b - A ) <-> N || ( p - A ) ) )')
s3 = w.s([], 'oveq1', '( b = p -> ( b gcd M ) = ( p gcd M ) )'); s4 = w.s([s3], 'eqeq1d', '( b = p -> ( ( b gcd M ) = 1 <-> ( p gcd M ) = 1 ) )')
s5 = w.s([s2, s4], 'anbi12d', '( b = p -> ( ( N || ( b - A ) /\\ ( b gcd M ) = 1 ) <-> ( N || ( p - A ) /\\ ( p gcd M ) = 1 ) ) )')
rs = w.s([pz, bo, w.s([s5], 'rspcev', '( ( p e. ZZ /\\ ( N || ( p - A ) /\\ ( p gcd M ) = 1 ) ) -> E. b e. ZZ ( N || ( b - A ) /\\ ( b gcd M ) = 1 ) )')], 'syl2anc', '( %s -> E. b e. ZZ ( N || ( b - A ) /\\ ( b gcd M ) = 1 ) )' % A2)
w.qed([ex, rs], 'rexlimddv', '( %s -> E. b e. ZZ ( N || ( b - A ) /\\ ( b gcd M ) = 1 ) )' % HC); run(w)

# ---- dchrzrh0: a character vanishes at the class of an integer not coprime to the level
H0 = '( ( N e. NN /\\ X e. %s ) /\\ A e. ZZ /\\ -. ( A gcd N ) = 1 )' % DB('N')
w = W('dchrzrh0', 'A Dirichlet character vanishes at the class of an integer not coprime to the level (Mathlib MulChar.map_nonunit in the integer idiom).')
g, z, d, l = dchr_hyps(w, 'N'); b = w.s([], 'eqid', '%s = %s' % (BZ('N'), BZ('N'))); u = w.s([], 'eqid', '%s = %s' % (UZ('N'), UZ('N')))
n = w.s([w.s([], 'simp1', '( %s -> ( N e. NN /\\ X e. %s ) )' % (H0, DB('N')))], 'simpld', '( %s -> N e. NN )' % H0)
x = w.s([w.s([], 'simp1', '( %s -> ( N e. NN /\\ X e. %s ) )' % (H0, DB('N')))], 'simprd', '( %s -> X e. %s )' % (H0, DB('N')))
a = w.s([], 'simp2', '( %s -> A e. ZZ )' % H0); nc = w.s([], 'simp3', '( %s -> -. ( A gcd N ) = 1 )' % H0)
n0 = w.s([n], 'nnnn0d', '( %s -> N e. NN0 )' % H0)
LA = '( %s ` A )' % LZ('N')
fo = w.s([n0, w.s([z, b, l], 'znzrhfo', '( N e. NN0 -> %s : ZZ -onto-> %s )' % (LZ('N'), BZ('N')))], 'syl', '( %s -> %s : ZZ -onto-> %s )' % (H0, LZ('N'), BZ('N')))
lab = w.s([w.s([fo, w.inst('fof')], 'syl', '( %s -> %s : ZZ --> %s )' % (H0, LZ('N'), BZ('N'))), a], 'ffvelcdmd', '( %s -> %s e. %s )' % (H0, LA, BZ('N')))
n0b = w.s([g, z, d, b, u, x, lab], 'dchrn0', '( %s -> ( ( X ` %s ) =/= 0 <-> %s e. %s ) )' % (H0, LA, LA, UZ('N')))
un = w.s([n0, a, w.s([z, u, l], 'znunit', '( ( N e. NN0 /\\ A e. ZZ ) -> ( %s e. %s <-> ( A gcd N ) = 1 ) )' % (LA, UZ('N')))], 'syl2anc', '( %s -> ( %s e. %s <-> ( A gcd N ) = 1 ) )' % (H0, LA, UZ('N')))
bb = w.s([n0b, un], 'bitrd', '( %s -> ( ( X ` %s ) =/= 0 <-> ( A gcd N ) = 1 ) )' % (H0, LA))
nn = w.s([nc, bb], 'mtbird', '( %s -> -. ( X ` %s ) =/= 0 )' % (H0, LA))
w.qed([nn, w.s([], 'nne', '( -. ( X ` %s ) =/= 0 <-> ( X ` %s ) = 0 )' % (LA, LA))], 'sylib', '( %s -> ( X ` %s ) = 0 )' % (H0, LA)); run(w)

# ---- dchrindinj: the inducing map is injective (Mathlib changeLevel_injective)
HJ = '( %s /\\ X e. %s /\\ Z e. %s )' % (H3, DB('N'), DB('N'))
Y = IND('N', 'M', 'X'); YZ = IND('N', 'M', 'Z')
w = W('dchrindinj', 'The inducing map is injective (Mathlib changeLevel_injective): two characters mod N with the same induced character mod M are equal. The lifting coprmlift supplies, for every integer coprime to N, a congruent integer coprime to M at which both induced characters can be read.')
h3 = w.s([], 'simp1', '( %s -> %s )' % (HJ, H3)); n = w.s([h3], 'simp1d', '( %s -> N e. NN )' % HJ); m = w.s([h3], 'simp2d', '( %s -> M e. NN )' % HJ)
x = w.s([], 'simp2', '( %s -> X e. %s )' % (HJ, DB('N'))); zc = w.s([], 'simp3', '( %s -> Z e. %s )' % (HJ, DB('N')))
bk = w.s([], 'fveq2', '( X = Z -> %s = %s )' % (Y, YZ))
bk2 = w.s([bk], 'a1i', '( %s -> ( X = Z -> %s = %s ) )' % (HJ, Y, YZ))
A1 = '( %s /\\ %s = %s )' % (HJ, Y, YZ); A2 = '( %s /\\ a e. ZZ )' % A1; A3 = '( %s /\\ %s )' % (A2, COP('a', 'N'))
n3 = w.s([n], 'ad3antrrr', '( %s -> N e. NN )' % A3); m3 = w.s([m], 'ad3antrrr', '( %s -> M e. NN )' % A3)
a3 = w.s([], 'simplr', '( %s -> a e. ZZ )' % A3); c3 = w.s([], 'simpr', '( %s -> %s )' % (A3, COP('a', 'N')))
lift = w.s([w.s([n3, m3], 'jca', '( %s -> ( N e. NN /\\ M e. NN ) )' % A3), a3, c3, w.inst('coprmlift')], 'syl3anc', '( %s -> E. b e. ZZ ( N || ( b - a ) /\\ %s ) )' % (A3, COP('b', 'M')))
A4 = '( %s /\\ ( b e. ZZ /\\ ( N || ( b - a ) /\\ %s ) ) )' % (A3, COP('b', 'M'))
bz = w.s([], 'simprl', '( %s -> b e. ZZ )' % A4); bd = w.s([w.s([], 'simprr', '( %s -> ( N || ( b - a ) /\\ %s ) )' % (A4, COP('b', 'M')))], 'simpld', '( %s -> N || ( b - a ) )' % A4)
bc = w.s([w.s([], 'simprr', '( %s -> ( N || ( b - a ) /\\ %s ) )' % (A4, COP('b', 'M')))], 'simprd', '( %s -> %s )' % (A4, COP('b', 'M')))
n4 = w.s([n3], 'adantr', '( %s -> N e. NN )' % A4); a4 = w.s([a3], 'adantr', '( %s -> a e. ZZ )' % A4)
h34 = w.s([h3], 'ad4antr', '( %s -> %s )' % (A4, H3)); x4 = w.s([x], 'ad4antr', '( %s -> X e. %s )' % (A4, DB('N'))); z4 = w.s([zc], 'ad4antr', '( %s -> Z e. %s )' % (A4, DB('N')))
eq4 = w.s([w.s([], 'id', '( %s = %s -> %s = %s )' % (Y, YZ, Y, YZ))], 'ad4antlr', '( %s -> %s = %s )' % (A4, Y, YZ))
zz, zl = w.s([], 'eqid', '( Z/nZ ` N ) = ( Z/nZ ` N )'), w.s([], 'eqid', '%s = %s' % (LZ('N'), LZ('N')))
LB = '( %s ` b )' % LZ('N'); LA = '( %s ` a )' % LZ('N')
zd = w.s([w.s([n4], 'nnnn0d', '( %s -> N e. NN0 )' % A4), bz, a4, w.s([zz, zl], 'zndvds', '( ( N e. NN0 /\\ b e. ZZ /\\ a e. ZZ ) -> ( %s = %s <-> N || ( b - a ) ) )' % (LB, LA))], 'syl3anc', '( %s -> ( %s = %s <-> N || ( b - a ) ) )' % (A4, LB, LA))
lba = w.s([bd, zd], 'mpbird', '( %s -> %s = %s )' % (A4, LB, LA))
e1 = w.s([lba], 'fveq2d', '( %s -> ( X ` %s ) = ( X ` %s ) )' % (A4, LB, LA)); e5 = w.s([lba], 'fveq2d', '( %s -> ( Z ` %s ) = ( Z ` %s ) )' % (A4, LB, LA))
hx4 = w.s([h34, x4], 'jca', '( %s -> ( %s /\\ X e. %s ) )' % (A4, H3, DB('N'))); hz4 = w.s([h34, z4], 'jca', '( %s -> ( %s /\\ Z e. %s ) )' % (A4, H3, DB('N')))
LMB = '( %s ` b )' % LZ('M')
e2 = w.s([hx4, bz, bc, w.inst('dchrindval1')], 'syl3anc', '( %s -> ( %s ` %s ) = ( X ` %s ) )' % (A4, Y, LMB, LB))
e3 = w.s([eq4], 'fveq1d', '( %s -> ( %s ` %s ) = ( %s ` %s ) )' % (A4, Y, LMB, YZ, LMB))
e4 = w.s([hz4, bz, bc, w.inst('dchrindval1')], 'syl3anc', '( %s -> ( %s ` %s ) = ( Z ` %s ) )' % (A4, YZ, LMB, LB))
e6 = w.s([e2, e3, e4], '3eqtr3d', '( %s -> ( X ` %s ) = ( Z ` %s ) )' % (A4, LB, LB))
e7 = w.s([e1, e6, e5], '3eqtr3d', '( %s -> ( X ` %s ) = ( Z ` %s ) )' % (A4, LA, LA))
e8 = w.s([lift, e7], 'rexlimddv', '( %s -> ( X ` %s ) = ( Z ` %s ) )' % (A3, LA, LA))
e9 = w.s([e8], 'ex', '( %s -> ( %s -> ( X ` %s ) = ( Z ` %s ) ) )' % (A2, COP('a', 'N'), LA, LA))
e10 = w.s([e9], 'ralrimiva', '( %s -> A. a e. ZZ ( %s -> ( X ` %s ) = ( Z ` %s ) ) )' % (A1, COP('a', 'N'), LA, LA))
eqz = w.s([w.s([n], 'adantr', '( %s -> N e. NN )' % A1), w.s([x], 'adantr', '( %s -> X e. %s )' % (A1, DB('N'))), w.s([zc], 'adantr', '( %s -> Z e. %s )' % (A1, DB('N'))), w.inst('dchreqz')], 'syl3anc', '( %s -> ( X = Z <-> A. a e. ZZ ( %s -> ( X ` %s ) = ( Z ` %s ) ) ) )' % (A1, COP('a', 'N'), LA, LA))
e11 = w.s([e10, eqz], 'mpbird', '( %s -> X = Z )' % A1)
e12 = w.s([e11], 'ex', '( %s -> ( %s = %s -> X = Z ) )' % (HJ, Y, YZ))
w.qed([e12, bk2], 'impbid', '( %s -> ( %s = %s <-> X = Z ) )' % (HJ, Y, YZ)); run(w)

# ---- dchrindmulval: the value of a product of two induced characters at an integer (CRT, pointwise)
UV = '( U x. V )'
HV = '( ( U e. NN /\\ V e. NN ) /\\ ( X e. %s /\\ Z e. %s ) /\\ A e. ZZ )' % (DB('U'), DB('V'))
YU = IND('U', UV, 'X'); YV = IND('V', UV, 'Z'); PR = '( %s %s %s )' % (YU, MUL(UV), YV)
LA = '( %s ` A )' % LZ(UV)
w = W('dchrindmulval', 'The value at an integer of the product of two characters induced to the product of their levels (LargeSieve changeLevel_mul_apply, Census prodChar_apply): the product of the values of the two characters. No coprimality of the two levels is needed.')
u = w.s([], 'simp1l', '( %s -> U e. NN )' % HV); v = w.s([], 'simp1r', '( %s -> V e. NN )' % HV)
x = w.s([], 'simp2l', '( %s -> X e. %s )' % (HV, DB('U'))); zc = w.s([], 'simp2r', '( %s -> Z e. %s )' % (HV, DB('V'))); a = w.s([], 'simp3', '( %s -> A e. ZZ )' % HV)
uz = w.s([u], 'nnzd', '( %s -> U e. ZZ )' % HV); vz = w.s([v], 'nnzd', '( %s -> V e. ZZ )' % HV)
uv = w.s([u, v], 'nnmulcld', '( %s -> %s e. NN )' % (HV, UV))
du = w.s([uz, vz, w.inst('dvdsmul1')], 'syl2anc', '( %s -> U || %s )' % (HV, UV)); dv = w.s([uz, vz, w.inst('dvdsmul2')], 'syl2anc', '( %s -> V || %s )' % (HV, UV))
hu = w.s([w.s([u, uv, du], '3jca', '( %s -> ( U e. NN /\\ %s e. NN /\\ U || %s ) )' % (HV, UV, UV)), x], 'jca', '( %s -> ( ( U e. NN /\\ %s e. NN /\\ U || %s ) /\\ X e. %s ) )' % (HV, UV, UV, DB('U')))
hv = w.s([w.s([v, uv, dv], '3jca', '( %s -> ( V e. NN /\\ %s e. NN /\\ V || %s ) )' % (HV, UV, UV)), zc], 'jca', '( %s -> ( ( V e. NN /\\ %s e. NN /\\ V || %s ) /\\ Z e. %s ) )' % (HV, UV, UV, DB('V')))
yu = w.s([hu, w.inst('dchrindcl')], 'syl', '( %s -> %s e. %s )' % (HV, YU, DB(UV))); yv = w.s([hv, w.inst('dchrindcl')], 'syl', '( %s -> %s e. %s )' % (HV, YV, DB(UV)))
z, b, l = w.s([], 'eqid', '( Z/nZ ` %s ) = ( Z/nZ ` %s )' % (UV, UV)), w.s([], 'eqid', '%s = %s' % (BZ(UV), BZ(UV))), w.s([], 'eqid', '%s = %s' % (LZ(UV), LZ(UV)))
fo = w.s([w.s([uv], 'nnnn0d', '( %s -> %s e. NN0 )' % (HV, UV)), w.s([z, b, l], 'znzrhfo', '( %s e. NN0 -> %s : ZZ -onto-> %s )' % (UV, LZ(UV), BZ(UV)))], 'syl', '( %s -> %s : ZZ -onto-> %s )' % (HV, LZ(UV), BZ(UV)))
lab = w.s([w.s([fo, w.inst('fof')], 'syl', '( %s -> %s : ZZ --> %s )' % (HV, LZ(UV), BZ(UV))), a], 'ffvelcdmd', '( %s -> %s e. %s )' % (HV, LA, BZ(UV)))
